public List<Map<String, Object>> execute(QueryRequest req) {
    return dataSourceService.executeWithDataSource(req.getDataSource(), () -> {
        // ① 模板渲染成 MyBatis 可执行 SQL（:param / {{#if}} / {{#in}}）
        String sql = sqlTemplateEngine.render(req.getTemplate(), req.getParams());
        // ② 入口净化：只允许 select/with，拦掉 13 类危险结构
        sqlSanitizer.checkSelect(sql);
        // ③ 按方言套分页壳，三种方言各自一段 if
        PagedSql paged = sqlPager.page(sql, req.getDataSource(), req.getOffset(), req.getLimit());
        return sqlExecutor.query(paged.getSql(), paged.getParamMap());
    });
}

public String normalize(String sql) {
    if (StringUtils.isBlank(sql)) {
        return "";
    }
    String s = sql.replaceAll("\\s+", " ").trim();        // 空白压缩，换行缩进不影响聚合
    s = s.replaceAll("\\?", "?");                        // 占位统一
    s = s.replaceAll("'[^']*'", "'?'");              // 字面量归一
    s = s.replaceAll("\\b\\d+\\b", "?");              // 数字归一
    return s.toUpperCase();
}

